def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_bid = []
    rich_aggressive_bid = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    urgent_opp_bid.append(float(bid))
                if opp.get('budget', 0) >= 140:
                    rich_aggressive_bid.append(float(bid))

    if not alive_opps:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 0.7
    elif hp <= 4:
        danger += 0.4
    if no_water >= 2:
        danger += 0.8
    elif no_water >= 1:
        danger += 0.35
    if day >= 8:
        danger += 0.15

    baseline = DAILY_SALARY * (0.28 + 0.32 * scarcity + danger)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    target = baseline

    if supply <= 17:
        if rich_aggressive_bid:
            target = max(target, max(rich_aggressive_bid) + 2.0)
        else:
            target = max(target, highest_prev + 1.5)
    elif danger >= 0.7:
        target = max(target, highest_prev + 1.0)
    elif danger >= 0.35:
        target = max(target, avg_prev * 0.92)
    else:
        if highest_prev >= DAILY_SALARY * 1.8:
            target = min(target, DAILY_SALARY * 0.35)
        elif highest_prev >= DAILY_SALARY * 1.2:
            target = min(target, DAILY_SALARY * 0.5)
        else:
            target = max(target, avg_prev * 0.75)

    if urgent_opp_bid and danger < 0.35 and supply >= 20:
        target = min(target, DAILY_SALARY * 0.38)

    reserve_days = max(1, 11 - day)
    soft_cap = budget / float(reserve_days)
    if danger < 0.35:
        target = min(target, soft_cap * 1.15)
    elif danger < 0.7:
        target = min(target, max(soft_cap * 1.6, target))
    else:
        target = min(max(target, soft_cap * 1.4), budget)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water >= 1:
        target = max(target, DAILY_SALARY * 0.7)

    target = max(0.0, min(float(budget), float(target)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Basic safety: if no budget, bid 0
    if my_status.get('budget', 0) <= 0:
        return 0

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 1)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        # If alone, try to secure water cheaply
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids as a proxy for today's aggressiveness
    yesterday_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many days we can cover if we win water each day (approx)
    # Budget is in money; winning water costs bid, then you still earn salary.
    # We'll keep a conservative reserve.
    reserve_days = 3
    approx_daily_cost_cap = DAILY_SALARY * 0.7

    # Determine target bid based on pressure and our hp
    # If yesterday had very high bids, others likely compete; bid enough to avoid losing.
    pressure_threshold = DAILY_SALARY * 0.85

    # If my hp is low, prioritize winning now.
    if hp <= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 4:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # Adjust with yesterday's highest bid
    if highest_prev_bid >= pressure_threshold:
        # Others were willing to pay near salary; match slightly below top to remain safe.
        target = min(base + 10.0, highest_prev_bid * 0.92)
    else:
        # If yesterday wasn't extreme, outbid moderately.
        target = max(base, highest_prev_bid * 0.6 + 5.0)

    # Budget-aware cap: don't spend more than we can reasonably sustain
    # across remaining episode (unknown exact total), use a conservative cap.
    cap = min(budget, approx_daily_cost_cap)
    bid = min(target, cap)

    # If supply is low, competition likely increases; nudge upward.
    try:
        if float(supply) <= float(MIN_SUPPLY) + 0.5:
            bid = min(budget, bid + 8.0)
    except Exception:
        pass

    # Ensure non-negative
    if bid < 0:
        bid = 0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev = sum(prev_bids) / len(prev_bids)
    max_prev = max(prev_bids)

    if my_status['hp'] < 4:
        return min(my_status['budget'], max_prev * 1.1 + 5.0)

    if supply / (len(alive_opponents) + 1) >= WATER_REQ:
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    return min(my_status['budget'], avg_prev * 1.05)
